Ltac acc_fs0 AC FO MU3 WFS RF FF ACn :=
  lazymatch type of AC with accessible _ ?a ?k =>
  lazymatch type of FO with fsobj _ _ ?O ?n =>
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    assert (ACn : accessible mc a k)
      by (eapply (accessible_fs0 _ HH _ _ _ _ _ mc O n a k); [exact RF| exact FF| exact FO| lia| lia| unfold AAPP_HI in *; lia| lia| lia| exact AC| exact MU3| exact WFS])
  end end end.

