Definition rs_consume_post (ra sp gp tp t0 t1 t2 s0 s1 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (stb k : Z) (FB : fbv) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a1 a2 a3 a4 a5 a6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 (stb + 152)) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 0xccbd8) fc None m' (seg_rom asegs)
    /\ munch [(stb + 152, stb + 168)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ rw_cells asegs m' (stb + 144) (FlatBufCells (fb_consume FB k)).

Lemma rs_consume : forall (stb k : Z) (FB : fbv) ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s6 s7 s8 s9 s10 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  rw_cells asegs m (stb + 144) (FlatBufCells FB) -> accessible m stb SZ_SPCI_STATE -> aapp stb SZ_SPCI_STATE -> stb mod 16 = 0 ->
  0 <= fb_begin FB -> fb_begin FB <= fb_in FB <= fb_out FB -> fb_out FB <= fb_last FB <= fb_end FB -> fb_end FB <= aceil ->
  0 <= k <= fb_size FB ->
  mem_inv asegs m ->
  evt asegs (rs_consume_post ra sp gp tp t0 t1 t2 s0 s1 a7 s2 s3 s4 (Z_to_bv 64 k) s6 s7 s8 s9 s10 (Z_to_bv 64 2147450880) t3 t4 t5 t6 F fc stb k FB m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 (stb + 32)) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 (Z_to_bv 64 k) s6 s7 s8 s9 s10 (Z_to_bv 64 2147450880) t3 t4 t5 t6)
