Lemma fb_consume_same : forall F k,
  fb_begin (fb_consume F k) = fb_begin F /\ fb_end (fb_consume F k) = fb_end F /\ fb_cap (fb_consume F k) = fb_cap F
  /\ fb_last (fb_consume F k) = fb_last F.
Proof. intros F k. unfold fb_consume, fb_cap. destruct (k <? fb_size F); cbn [fb_begin fb_end fb_last]; repeat split; reflexivity. Qed.
