Lemma rs_D : forall (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (rax t0' t1' t2' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word)
    (bs stb ioc implb MB tgt tn ec spa lo shi ff fp : Z) (LB : list block) (LF : list fframe) (S : statev) (ds junk : list byte) (E : ecv)
    (m mx : mem),
  rs_inv H ra sp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 bs stb ioc implb MB tgt tn ec spa lo shi ff fp LB LF S ds junk E m mx ->
  fb_in (st_fb S) <> fb_out (st_fb S) ->
  evt asegs (readsome_post H ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LB LF stb ioc implb tgt tn ec lo shi S ds junk E m)
    (MS (mkR rax (Z_to_bv 64 spa) gp tp t0' t1' t2' sp (Z_to_bv 64 spa) (Z_to_bv 64 (stb + 32)) a1' a2' a3' a4' a5' a6' a7'
             (Z_to_bv 64 ec) (Z_to_bv 64 bs) (Z_to_bv 64 (ff + 32)) (Z_to_bv 64 (fb_out (st_fb S)))
             (Z_to_bv 64 (Z.shiftr (MB + 8) 3 + 2147450880)) (Z_to_bv 64 (MB + 8)) (Z_to_bv 64 (fb_in (st_fb S)))
             (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) (Z_to_bv 64 ff) (Z_to_bv 64 2147450880) t3' t4' t5' t6')
